SELECT COUNT(DISTINCT s.PATIENT)
FROM syn_stays s
INNER JOIN syn_risk_scores r ON s.PATIENT = r.PATIENT AND s.START = r.START AND s.STOP = r.STOP;

SELECT reason, AVG(lace) AS avg_lace_score
